/* eslint-disable */
/* global WebImporter */

// AUTO-GENERATED by tools/importer/gen-import-scripts.mjs — one script per template.
// Orchestrates block parsers + site-wide transformers (cleanup -> links -> sections).

// PARSER IMPORTS
import cardsBylineParser from './parsers/cards-byline.js';

// TRANSFORMER IMPORTS
import cleanupTransformer from './transformers/wknd-cleanup.js';
import linksTransformer from './transformers/wknd-links.js';
import sectionsTransformer from './transformers/wknd-sections.js';

// PARSER REGISTRY
const parsers = {
  'cards-byline': cardsBylineParser,
};

/**
 * Restructure the "SHARE THIS STORY" related-articles list so each item's TITLE
 * and DATE survive the Markdown round-trip as two distinct lines (matching the
 * source, which wraps them in separate `.cmp-list__item-title` /
 * `.cmp-list__item-date` spans inside the link).
 *
 * The source markup is `<li><a><span title/><span date/></a></li>`. A markdown
 * link can only hold inline text, so both spans collapse into one flat link
 * ("Title Date") with no way to style/line-break them apart. We rewrite each
 * item to `<li><a>Title</a><br>Date</li>` — the link keeps only the title (the
 * clickable headline), and the date follows as plain text after a hard break, so
 * CSS can render the title over a muted date line.
 * @param {Document} document
 */
function restructureRelatedList(document) {
  const items = document.querySelectorAll('aside ul li, .cmp-list__item');
  items.forEach((li) => {
    const link = li.querySelector('a');
    if (!link) return;
    const titleEl = link.querySelector('.cmp-list__item-title');
    const dateEl = link.querySelector('.cmp-list__item-date');
    // Prefer the explicit spans; fall back to splitting a "Title … <date>" string
    // on the trailing weekday-led date if the spans were already stripped.
    let title;
    let date;
    if (titleEl && dateEl) {
      title = titleEl.textContent.trim();
      date = dateEl.textContent.trim();
    } else {
      const m = link.textContent.trim().match(/^(.*?)\s+((?:Mon|Tues|Wednes|Thurs|Fri|Satur|Sun)day,.*)$/);
      if (!m) return;
      [, title, date] = m;
    }
    link.textContent = title; // link = clickable headline only
    li.replaceChildren(link, document.createElement('br'), document.createTextNode(date));
  });
}

// Author-controlled display order per magazine slug. The dynamic magazine-cards
// block sorts by this ascending, then applies its `limit` — so the homepage
// "Recent Articles" grid (limit 4) shows orders 1–4. Seeded to the live source's
// homepage order (guide-la-skateparks, ski-touring, arctic-surfing,
// san-diego-surf), with western-australia last since the source features it
// separately above the grid rather than inside it. Injected as an "Order"
// metadata row so the magazine query-index exposes an `order` column. Change a
// page's number to reorder the homepage cards without touching code.
const SLUG_ORDER = {
  'guide-la-skateparks': 1,
  'ski-touring': 2,
  'arctic-surfing': 3,
  'san-diego-surf': 4,
  'western-australia': 5,
};

/**
 * Append a `<tr><td>key</td><td>value</td></tr>` row to the Metadata block that
 * WebImporter.rules.createMetadata produced. createMetadata emits a <table> whose
 * header cell reads "Metadata" (the `.metadata` class only appears after the
 * md2da conversion, so match by header text here). No-op if the value is empty
 * or the metadata table isn't found.
 * @param {Element} main document.body after createMetadata has run
 * @param {Document} document
 * @param {string} key the metadata key (becomes a `<meta name="key">`)
 * @param {string} value the metadata value
 */
function appendMetadataRow(main, document, key, value) {
  if (!value) return;
  const metaTable = [...main.querySelectorAll('table')].reverse().find((t) => {
    const head = t.querySelector('th, td');
    return head && head.textContent.trim().toLowerCase() === 'metadata';
  });
  if (!metaTable) return;

  const tr = document.createElement('tr');
  const keyCell = document.createElement('td');
  keyCell.textContent = key;
  const valCell = document.createElement('td');
  valCell.textContent = value;
  tr.append(keyCell, valCell);
  metaTable.append(tr);
}

/**
 * Append an "Order" row to the Metadata block, using the magazine slug from the
 * page URL. Becomes a `<meta name="order">` feeding the magazine query-index
 * `order` column, which the magazine-cards block sorts by before applying limit.
 * @param {Element} main document.body after createMetadata has run
 * @param {Document} document
 * @param {string} originalURL the source page URL
 */
function injectOrderMetadata(main, document, originalURL) {
  const slug = new URL(originalURL).pathname.match(/\/magazine\/([^./?#]+)/)?.[1];
  const order = slug && SLUG_ORDER[slug];
  appendMetadataRow(main, document, 'Order', order ? String(order) : '');
}

// PAGE TEMPLATE CONFIGURATION — embedded from page-templates.json
const PAGE_TEMPLATE = {
  "name": "magazine-article",
  "description": "Magazine article page (5 pages, structurally identical). Structure: (1) article body (main.cmp-layout-container--fixed): full-bleed lead image + H1 + byline (h4) + long-form rich text (paragraphs, a blockquote pull-quote, H2 subheads, inline images) -> ALL DEFAULT CONTENT; (2) author bio experience fragment (portrait + name h2 + role + social icon links) -> cards-byline (new horizontal author-card variant); (3) related-articles sidebar (aside.cmp-layoutcontainer--sidebar: 'SHARE THIS STORY' h5 + a list of 4 related-article links with dates, hrefs -> /us/en/magazine/<slug>.html) -> default content. The footer teaser (Follow Us) and breadcrumb are site chrome, not page content.",
  "urls": [
    "https://wknd.site/us/en/magazine/arctic-surfing.html",
    "https://wknd.site/us/en/magazine/guide-la-skateparks.html",
    "https://wknd.site/us/en/magazine/san-diego-surf.html",
    "https://wknd.site/us/en/magazine/ski-touring.html",
    "https://wknd.site/us/en/magazine/western-australia.html"
  ],
  "blocks": [
    {
      "name": "cards-byline",
      "instances": [
        "main main div.experiencefragment"
      ]
    }
  ],
  "sections": [
    {
      "id": "rc1",
      "name": "Article Body",
      "selector": "main main.container.responsivegrid.cmp-layout-container--fixed",
      "style": null,
      "blocks": [
        "cards-byline"
      ],
      "defaultContent": [
        "main main.container.responsivegrid.cmp-layout-container--fixed h1",
        "main main.container.responsivegrid.cmp-layout-container--fixed h4",
        "main main.container.responsivegrid.cmp-layout-container--fixed article"
      ]
    },
    {
      "id": "rc3",
      "name": "Related Articles",
      "selector": "aside.container.responsivegrid.cmp-layoutcontainer--sidebar",
      "style": null,
      "blocks": [],
      "defaultContent": [
        "aside.container.responsivegrid.cmp-layoutcontainer--sidebar h5",
        "aside.container.responsivegrid.cmp-layoutcontainer--sidebar ul"
      ]
    }
  ]
};

// TRANSFORMER REGISTRY (cleanup + links always run; sections only for multi-section templates)
const transformers = [
  cleanupTransformer,
  linksTransformer,
  ...(PAGE_TEMPLATE.sections && PAGE_TEMPLATE.sections.length > 1 ? [sectionsTransformer] : []),
];

/**
 * Execute all page transformers for a specific hook.
 * @param {string} hookName 'beforeTransform' | 'afterTransform'
 * @param {Element} element DOM element (document.body)
 * @param {Object} payload { document, url, html, params }
 */
function executeTransformers(hookName, element, payload) {
  const enhancedPayload = { ...payload, template: PAGE_TEMPLATE };
  transformers.forEach((transformerFn) => {
    try {
      transformerFn.call(null, hookName, element, enhancedPayload);
    } catch (e) {
      console.error(`Transformer failed at ${hookName}:`, e);
    }
  });
}

/**
 * Find all blocks on the page based on the embedded template configuration.
 * @param {Document} document
 * @param {Object} template PAGE_TEMPLATE
 * @returns {Array} block instances found on the page
 */
function findBlocksOnPage(document, template) {
  const pageBlocks = [];
  template.blocks.forEach((blockDef) => {
    blockDef.instances.forEach((selector) => {
      let elements = [];
      try {
        elements = document.querySelectorAll(selector);
      } catch (e) {
        console.warn(`Invalid selector for "${blockDef.name}": ${selector}`);
        return;
      }
      if (elements.length === 0) {
        console.warn(`Block "${blockDef.name}" selector not found: ${selector}`);
      }
      elements.forEach((element) => {
        pageBlocks.push({
          name: blockDef.name,
          selector,
          element,
          section: blockDef.section || null,
        });
      });
    });
  });
  console.log(`Found ${pageBlocks.length} block instances on page`);
  return pageBlocks;
}

export default {
  transform: (payload) => {
    const {
      document, url, html, params,
    } = payload;

    const main = document.body;

    // 1. beforeTransform (initial cleanup)
    executeTransformers('beforeTransform', main, payload);

    // 1b. Restructure the related-articles ("SHARE THIS STORY") list so each
    // item's title and date survive as two lines (source parity). Runs while the
    // `.cmp-list__item-title`/`-date` spans still exist, before md conversion.
    restructureRelatedList(document);

    // 2. Discover blocks from embedded template
    const pageBlocks = findBlocksOnPage(document, PAGE_TEMPLATE);

    // 3. Parse each block (skip elements already replaced by a prior parser)
    pageBlocks.forEach((block) => {
      if (!block.element.parentNode) return;
      const parser = parsers[block.name];
      if (parser) {
        try {
          parser(block.element, { document, url, params });
        } catch (e) {
          console.error(`Failed to parse ${block.name} (${block.selector}):`, e);
        }
      } else {
        console.warn(`No parser found for block: ${block.name}`);
      }
    });

    // 4. afterTransform (final cleanup + link remap + section breaks/metadata)
    executeTransformers('afterTransform', main, payload);

    // 5. WebImporter built-in rules
    const hr = document.createElement('hr');
    main.appendChild(hr);
    WebImporter.rules.createMetadata(main, document);
    // add an Order metadata row so the magazine query-index exposes an `order`
    // column the magazine-cards block sorts by before applying its limit.
    injectOrderMetadata(main, document, params.originalURL);
    WebImporter.rules.transformBackgroundImages(main, document);
    WebImporter.rules.adjustImageUrls(main, url, params.originalURL);

    // 6. Sanitized path (map root/homepage to /index to avoid empty-path crash)
    const rawPath = new URL(params.originalURL).pathname
      .replace(/\/$/, '')
      .replace(/\.html?$/, '');
    const path = WebImporter.FileUtils.sanitizePath(rawPath === '' ? '/index' : rawPath);

    return [{
      element: main,
      path,
      report: {
        title: document.title,
        template: PAGE_TEMPLATE.name,
        blocks: pageBlocks.map((b) => b.name),
      },
    }];
  },
};
